package com.brightloop.config;

import com.brightloop.catalog.*;
import com.brightloop.discount.*;
import com.brightloop.invoice.*;
import com.brightloop.payment.*;
import com.brightloop.plan.*;
import com.brightloop.quotation.QuotationTemplateService;
import com.brightloop.subscription.*;
import com.brightloop.tax.*;
import com.brightloop.user.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration @Profile("dev")
public class DemoData {
    @Bean CommandLineRunner seedUsers(AppUserRepository users,PasswordEncoder encoder,CustomerRepository customers,ProductRepository products,ProductVariantRepository variants,PlanRepository plans,TaxRepository taxes,DiscountRepository discounts,SubscriptionRepository subscriptions,InvoiceRepository invoices,InvoiceLineRepository invoiceLines,PaymentRepository payments,QuotationTemplateService templateService){return args->{
        create(users,encoder,"admin@brightloop.com","Admin@12345","Jamie Davis",Role.ADMIN);
        create(users,encoder,"staff@brightloop.com","Staff@12345","Taylor Morgan",Role.STAFF);
        create(users,encoder,"customer@brightloop.com","Customer@12345","Olivia Rhye",Role.CUSTOMER);
        if(customers.count()==0){String[][] sample={{"Olivia Rhye","olivia@layers.com","Layers"},{"Phoenix Baker","phoenix@catalog.com","Catalog"},{"Lana Steiner","lana@circooles.com","Circooles"},{"Demi Wilkinson","demi@commandr.com","Command+R"},{"Candice Wu","candice@hourglass.com","Hourglass"},{"Natali Craig","natali@quotient.com","Quotient"},{"Drew Cano","drew@sisyphus.com","Sisyphus"},{"Orlando Diggs","orlando@bloom.com","Bloom"},{"Andi Lane","andi@acme.com","Acme"},{"Kate Morrison","kate@northstar.com","Northstar"},{"Olivia Rhye","customer@brightloop.com","Brightloop Demo"}};for(String[] c:sample)customers.save(new Customer(c[0],c[1],"+1 555 0100",c[2],"", "New York","NY","United States","10001",null));}
        if(products.count()==0){Product software=products.save(new Product("Brightloop Business","Software","Subscription management for growing teams.",new BigDecimal("200.00"),new BigDecimal("42.00"),"Popular workspace plan","ACTIVE"));variants.save(new ProductVariant(software,"Standard","1 workspace",BigDecimal.ZERO,"ACTIVE"));variants.save(new ProductVariant(software,"Premium","Advanced analytics",new BigDecimal("100.00"),"ACTIVE"));Product insights=products.save(new Product("Revenue Insights","Analytics","Understand recurring revenue and retention.",new BigDecimal("80.00"),new BigDecimal("18.00"),"Analytics add-on","ACTIVE"));variants.save(new ProductVariant(insights,"Pro","Unlimited reports",new BigDecimal("40.00"),"ACTIVE"));}
        if(products.count()<8){String[][] extra={{"Customer Success Suite","Software","Customer engagement tools.","120.00","28.00"},{"Workflow Automation","Software","Automate recurring operational work.","95.00","20.00"},{"Team Workspace","Collaboration","Shared workspaces for distributed teams.","65.00","14.00"},{"Secure Archive","Storage","Encrypted long-term document storage.","35.00","8.00"},{"Priority Support","Service","Priority technical support coverage.","150.00","52.00"},{"Commerce Connect","Integration","Connect subscription billing to commerce tools.","110.00","31.00"}};int n=0;while(products.count()<8){String[] p=extra[n++];Product added=products.save(new Product(p[0],p[1],p[2],new BigDecimal(p[3]),new BigDecimal(p[4]),"Demo catalog item","ACTIVE"));variants.save(new ProductVariant(added,"Standard","Standard package",BigDecimal.ZERO,"ACTIVE"));variants.save(new ProductVariant(added,"Plus","Expanded package",new BigDecimal("25.00"),"ACTIVE"));}}
        if(plans.count()==0){Product p=products.findAll().get(0);plans.save(new Plan(p,"Starter","For teams getting started.",new BigDecimal("49.00"),BillingFrequency.MONTHLY,1,null,null,true,true,true,true,"ACTIVE"));plans.save(new Plan(p,"Growth","For teams building momentum.",new BigDecimal("249.00"),BillingFrequency.MONTHLY,1,null,null,true,true,true,true,"ACTIVE"));plans.save(new Plan(p,"Scale","For fast-growing businesses.",new BigDecimal("1890.00"),BillingFrequency.YEARLY,1,LocalDate.now().minusYears(1),null,true,true,true,true,"ACTIVE"));}
        if(plans.count()<6){List<Product> catalog=products.findAll();String[][] more={{"Launch","79.00","MONTHLY"},{"Pro Annual","990.00","YEARLY"},{"Flexible Weekly","25.00","WEEKLY"}};int n=0;while(plans.count()<6){String[] p=more[n++];plans.save(new Plan(catalog.get(n%catalog.size()),p[0],"Demo plan with configurable subscription lifecycle.",new BigDecimal(p[1]),BillingFrequency.valueOf(p[2]),1,null,null,true,true,true,true,"ACTIVE"));}}
        if(taxes.count()==0)taxes.save(new Tax("Sales tax","PERCENTAGE",new BigDecimal("8.2500"),"Development sample tax",null,null,null,true));
        if(discounts.count()==0)discounts.save(new Discount("FALL20","Fall promotion","PERCENTAGE",new BigDecimal("20.0000"),LocalDate.now().minusDays(1),LocalDate.now().plusDays(60),500,true));
        if(discounts.count()<5){seedDiscount(discounts,"START10","Starter offer","10.0000");seedDiscount(discounts,"ANNUAL15","Annual plan offer","15.0000");seedDiscount(discounts,"WELCOME5","Welcome offer","5.0000");seedDiscount(discounts,"TEAM25","Team launch offer","25.0000");}
        if(templateService.list().isEmpty()){Long productId=products.findAll().get(0).getId();Long planId=plans.findAll().get(1).getId();templateService.create(new QuotationTemplateService.Request("Growth offer","Default Brightloop Growth offer",14,List.of(new QuotationTemplateService.LineRequest(productId,planId,null,1))));templateService.create(new QuotationTemplateService.Request("Premium annual","Annual offer with premium variant",30,List.of(new QuotationTemplateService.LineRequest(productId,plans.findAll().get(2).getId(),variants.findByProductId(productId).get(1).getId(),1))));}
        if(subscriptions.count()==0){List<Customer> cs=customers.findAll();List<Plan> ps=plans.findAll();Product product=products.findAll().get(0);List<ProductVariant> productVariants=variants.findByProductId(product.getId());Tax tax=taxes.findAll().get(0);Discount fall=discounts.findByCodeIgnoreCase("FALL20").orElse(null);for(int i=0;i<10;i++){Customer customer=cs.get(i);Plan plan=ps.get(i%ps.size());ProductVariant variant=i%2==0?productVariants.get(0):productVariants.get(1);BigDecimal unit=plan.getBillingPrice().add(variant.getAdditionalPrice());int qty=i%3+1;BigDecimal subtotal=unit.multiply(BigDecimal.valueOf(qty)).setScale(2,RoundingMode.HALF_UP);BigDecimal taxAmount=subtotal.multiply(tax.getRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);BigDecimal discountAmount=i%3==0&&fall!=null?subtotal.multiply(fall.getValue()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):BigDecimal.ZERO;BigDecimal total=subtotal.add(taxAmount).subtract(discountAmount);LocalDate start=LocalDate.now().minusMonths(i%2==0?1:2);Subscription sub=new Subscription("SUB-DEMO-"+String.format("%04d",i+1),customer,plan,start,null,"Net 14",qty,unit,subtotal,taxAmount,discountAmount,total);sub.setDiscount(i%3==0?fall:null);sub.confirm();sub.activate();sub.billed(LocalDate.now().plusDays(i%20+1));if(i==8)sub.pause();if(i==9)sub.close(false);sub.addLine(new SubscriptionLine(sub,product,variant,plan.getName()+" · "+variant.getName(),qty,unit,tax.getRate()));sub= subscriptions.save(sub);LocalDate end=BillingService.advanceOne(start,plan.getBillingFrequency()).minusDays(1);Invoice invoice=invoices.save(new Invoice("INV-DEMO-"+String.format("%04d",i+1),customer,sub,null,start,end,LocalDate.now().minusDays(i+1),LocalDate.now().plusDays(14-i%9),subtotal,taxAmount,discountAmount,total));invoice.addLine(new InvoiceLine(invoice,product,plan.getName()+" · "+variant.getName(),qty,unit,tax.getRate(),taxAmount,total));if(i<8){invoice.applyPayment(total);invoice=invoices.save(invoice);payments.save(new Payment("PAY-DEMO-"+String.format("%04d",i+1),invoice,total,i%2==0?"CARD":"UPI","DEMO-"+(i+1),"Demo payment"));}else if(i<10){BigDecimal paid=total.divide(new BigDecimal("2"),2,RoundingMode.HALF_UP);invoice.applyPayment(paid);invoice=invoices.save(invoice);payments.save(new Payment("PAY-DEMO-"+String.format("%04d",2*(i-8)+9),invoice,paid,"BANK_TRANSFER","DEMO-"+(i+1)+"-A","Demo partial payment"));BigDecimal remaining=total.subtract(paid);invoice.applyPayment(remaining);invoice=invoices.save(invoice);payments.save(new Payment("PAY-DEMO-"+String.format("%04d",2*(i-8)+10),invoice,remaining,"CARD","DEMO-"+(i+1)+"-B","Demo balance payment"));}invoiceLines.saveAll(invoice.getLines());}
            for(int i=0;i<5;i++){Customer customer=cs.get(i+3);Product extra=products.findAll().get(1);BigDecimal subtotal=extra.getSalesPrice();BigDecimal taxAmount=subtotal.multiply(tax.getRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);Invoice invoice=invoices.save(new Invoice("INV-DEMO-"+String.format("%04d",i+11),customer,null,null,null,null,LocalDate.now().minusDays(i+2),LocalDate.now().minusDays(i%3),subtotal,taxAmount,BigDecimal.ZERO,subtotal.add(taxAmount)));invoice.addLine(new InvoiceLine(invoice,extra,"Revenue Insights",1,subtotal,tax.getRate(),taxAmount,subtotal.add(taxAmount)));invoiceLines.saveAll(invoice.getLines());}
        }
    };}
    private void create(AppUserRepository users,PasswordEncoder encoder,String email,String password,String name,Role role){if(!users.existsByEmailIgnoreCase(email))users.save(new AppUser(email,encoder.encode(password),name,role));}
    private void seedDiscount(DiscountRepository repository,String code,String name,String amount){if(!repository.existsByCodeIgnoreCase(code))repository.save(new Discount(code,name,"PERCENTAGE",new BigDecimal(amount),LocalDate.now().minusDays(1),LocalDate.now().plusDays(90),300,true));}
}
